import puppeteer from 'puppeteer-core';
const baseUrl=process.env.TEST_URL,executablePath=process.env.CHROME_PATH;if(!baseUrl||!executablePath)throw new Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],timeout:30000});
async function client(name,rating,appearance){const context=await browser.createBrowserContext(),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e?.stack||e?.message||e)));page.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource:.*404/i.test(m.text()))errors.push('console: '+m.text())});await page.evaluateOnNewDocument((n,r,a)=>{try{localStorage.setItem('BombermanPlayerName',n);localStorage.setItem('BombermanRatingV1',String(r));localStorage.setItem('BombermanScoreV1Initialized','1');localStorage.setItem('BombermanCharacterV1',JSON.stringify(a))}catch(e){}try{if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({scope:location.href})}catch(e){}},name,rating,appearance);await page.goto(baseUrl,{waitUntil:'domcontentloaded',timeout:20000});await page.waitForFunction(()=>window.BomberCharacter&&window.BomberDataSync&&B115.__dataSyncInstalled&&gGameEngine?.menu,{timeout:16000});return{context,page,errors}}
async function waitFor(fn,timeout=25000,step=200){const end=Date.now()+timeout;while(Date.now()<end){if(await fn())return true;await sleep(step)}return false}
async function diag(page){return page.evaluate(()=>({role:B115.role,kind:B115.kind,started:B115.started,conn:!!B115.conn,connOpen:!!B115.conn?.open,peerOpen:!!B115.peer?.open,path:window.BomberV125?.connectionPath||'',remoteName:B115.remoteName,localName:B115.localName,remote:BomberCharacter.getRemote(),localScore:BomberCharacter.getRating(),players:gGameEngine.players.map(p=>({rating:p.rating,appearance:p.characterAppearance,alive:p.alive})),status:B115.els.matchStatus?.textContent||'',v127:window.BomberV127?.version||''}))}
const hostAppearance={gender:'male',skin:'deep',glasses:true,hat:'cap',shoes:'red'};
const joinAppearance={gender:'female',skin:'light',glasses:false,hat:'beanie',shoes:'blue'};
let A,B;
try{
 A=await client('ProfileHost',620,hostAppearance);B=await client('ProfileJoin',840,joinAppearance);const peer='bomberman-v0123-profile-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);
 await A.page.evaluate(id=>{B115.privateId=()=>id;B115.els.privateCode.value='8';B115.els.name.value='ProfileHost';B115.startPrivateHost()},peer);await sleep(900);
 await B.page.evaluate(id=>{B115.privateId=()=>id;B115.els.privateCode.value='8';B115.els.name.value='ProfileJoin';B115.startPrivateJoin()},peer);
 const synced=await waitFor(async()=>{const [a,b]=await Promise.all([A.page.evaluate(()=>({started:B115.started,remote:BomberCharacter.getRemote(),p:gGameEngine.players[1]&&{rating:gGameEngine.players[1].rating,appearance:gGameEngine.players[1].characterAppearance}})),B.page.evaluate(()=>({started:B115.started,remote:BomberCharacter.getRemote(),p:gGameEngine.players[0]&&{rating:gGameEngine.players[0].rating,appearance:gGameEngine.players[0].characterAppearance}}))]);return a.started&&b.started&&a.remote?.rating===840&&b.remote?.rating===620&&a.p?.rating===840&&b.p?.rating===620&&a.p?.appearance?.skin==='light'&&b.p?.appearance?.skin==='deep'},25000,250);
 if(!synced){const [da,db]=await Promise.all([diag(A.page),diag(B.page)]);console.log('PROFILE_TIMEOUT_HOST',JSON.stringify(da));console.log('PROFILE_TIMEOUT_GUEST',JSON.stringify(db));console.log('PROFILE_ERRORS',JSON.stringify([...A.errors,...B.errors]));throw new Error('online character/score profiles did not synchronize')}
 const [a,b]=await Promise.all([A.page.evaluate(()=>({remote:BomberCharacter.getRemote(),localScore:BomberCharacter.getRating(),remotePlayer:{rating:gGameEngine.players[1].rating,appearance:gGameEngine.players[1].characterAppearance},status:B115.els.matchStatus.textContent})),B.page.evaluate(()=>({remote:BomberCharacter.getRemote(),localScore:BomberCharacter.getRating(),remotePlayer:{rating:gGameEngine.players[0].rating,appearance:gGameEngine.players[0].characterAppearance},status:B115.els.matchStatus.textContent}))]);
 console.log('PROFILE_HOST',JSON.stringify(a));console.log('PROFILE_JOIN',JSON.stringify(b));
 if(a.localScore!==620||b.localScore!==840)throw new Error('local scores changed during connection');
 if(a.remote.rating!==840||b.remote.rating!==620)throw new Error('remote scores wrong');
 if(JSON.stringify(a.remote.appearance)!==JSON.stringify(joinAppearance)||JSON.stringify(b.remote.appearance)!==JSON.stringify(hostAppearance))throw new Error('remote appearance payload wrong');
 if(a.remotePlayer.rating!==840||b.remotePlayer.rating!==620)throw new Error('remote entity score wrong');
 if(!a.status.includes('620')||!a.status.includes('840')||!b.status.includes('620')||!b.status.includes('840'))throw new Error('match bar does not show both scores');
 if(A.errors.length||B.errors.length)throw new Error('browser errors: '+[...A.errors,...B.errors].join(' | '));console.log('PROFILE_SYNC_SMOKE PASS');
}finally{await A?.context.close().catch(()=>{});await B?.context.close().catch(()=>{});await browser.close().catch(()=>{})}
